1	// Official entry point for evidence runs of the SignalScout pipelines.
2	//
3	//   npx tsx scripts/run-pipeline.ts --pipeline baseline
4	//   npx tsx scripts/run-pipeline.ts --pipeline baseline --llm real --confirm-spend
5	//
6	// Options: --pipeline baseline, --llm fake|real (default fake), --confirm-spend
7	// (required with --llm real), --label <string> (default: pipeline name),
8	// --config dev|eval (default eval).
9	//
10	// Writes runs/<timestamp>-<label>.json with counts, ids, costs, issue codes,
11	// tokens and timings only: no company records, keys or headers.
12	
13	import { mkdir, writeFile } from "node:fs/promises";
14	import { span } from "neatlogs";
15	import {
16	  FakeLlmClient,
17	  type LlmClient,
18	  type LlmRequest,
19	  type LlmResponse,
20	  type PipelineResult,
21	  PROMPT_SAFETY_RULES,
22	  PROMPT_VERSION,
23	  runBaselinePipeline,
24	} from "../src/core/agent";
25	import { createGatewayLlmClient } from "../src/core/agent/gateway-client";
26	import { neatlogsTracer } from "../src/core/agent/neatlogs-tracer";
27	import type { CompanyProvider } from "../src/core/data/provider";
28	import { FixtureProvider } from "../src/core/data/fixture-provider";
29	import { validateCompanies } from "../src/core/data/validation";
30	import { closeTracing, initTracing } from "../src/core/observability/tracing";
31	import {
32	  DEFAULT_RUN_CONFIG,
33	  DEV_RUN_CONFIG,
34	  type RawCompany,
35	  type RunConfig,
36	} from "../src/core/types";
37	import {
38	  type PostHocValidation,
39	  recordSystemHashes,
40	  sha256Hex,
41	  summarizeValidation,
42	} from "./run-metrics";
43	
44	// What the evidence ICP means in words; matches describeIcp for the open ICP.
45	const EVIDENCE_ICP_DESCRIPTION = "Companies in any industry of any size in any location.";
46	
47	// Simulated at measured Crustdata prices (USD per record).
48	const SIMULATED_COST_PER_RECORD = { search: 0.069, enrich: 0.6 } as const;
49	
50	const EVAL_RUN_CONFIG: RunConfig = {
51	  ...DEFAULT_RUN_CONFIG,
52	  max_search_results: 10,
53	  max_enrichments: 5,
54	};
55	
56	// The ICP every evidence run uses, so runs are comparable. Open: no industry,
57	// size, location or keyword filter, so it matches every fixture.
58	const EVIDENCE_ICP = {
59	  industry: "",
60	  employee_count_ranges: [],
61	  locations: [],
62	  keywords: [],
63	  excluded_domains: [],
64	};
65	
66	interface Args {
67	  readonly pipeline: "baseline";
68	  readonly llm: "fake" | "real";
69	  readonly confirm_spend: boolean;
70	  readonly label: string;
71	  readonly config: "dev" | "eval";
72	}
73	
74	class UsageError extends Error {}
75	
76	function parseArgs(argv: readonly string[]): Args {
77	  let pipeline: string | undefined;
78	  let llm = "fake";
79	  let confirm_spend = false;
80	  let label: string | undefined;
81	  let config = "eval";
82	  const value = (i: number, flag: string): string => {
83	    const v = argv[i + 1];
84	    if (v === undefined || v.startsWith("--")) throw new UsageError(`${flag} needs a value.`);
85	    return v;
86	  };
87	  for (let i = 0; i < argv.length; i++) {
88	    const flag = argv[i];
89	    switch (flag) {
90	      case "--pipeline":
91	        pipeline = value(i++, flag);
92	        break;
93	      case "--llm":
94	        llm = value(i++, flag);
95	        break;
96	      case "--label":
97	        label = value(i++, flag);
98	        break;
99	      case "--config":
100	        config = value(i++, flag);
101	        break;
102	      case "--confirm-spend":
103	        confirm_spend = true;
104	        break;
105	      default:
106	        throw new UsageError(`Unknown argument: ${flag}`);
107	    }
108	  }
109	  if (pipeline === undefined) throw new UsageError("--pipeline is required (baseline).");
110	  if (pipeline !== "baseline") {
111	    throw new UsageError(
112	      `Unsupported pipeline "${pipeline}". Only "baseline" exists; the improved pipeline is not built yet.`,
113	    );
114	  }
115	  if (llm !== "fake" && llm !== "real") throw new UsageError(`--llm must be fake or real, got "${llm}".`);
116	  if (config !== "dev" && config !== "eval") {
117	    throw new UsageError(`--config must be dev or eval, got "${config}".`);
118	  }
119	  if (llm === "real" && !confirm_spend) {
120	    throw new UsageError("--llm real spends money on the model gateway. Add --confirm-spend to proceed.");
121	  }
122	  const finalLabel = label ?? pipeline;
123	  if (finalLabel.trim() === "") throw new UsageError("--label must not be empty.");
124	  return { pipeline, llm, confirm_spend, label: finalLabel, config };
125	}
126	
127	function buildLlm(kind: Args["llm"]): LlmClient {
128	  if (kind === "fake") return new FakeLlmClient();
129	  const apiKey = process.env.LITELLM_API_KEY;
130	  if (apiKey === undefined || apiKey.trim() === "") {
131	    throw new UsageError("LITELLM_API_KEY is not set; it is required for --llm real.");
132	  }
133	  return createGatewayLlmClient({ apiKey });
134	}
135	
136	// Fake-client token counts are made up; only real gateway usage is measured.
137	function tokenBasis(kind: Args["llm"]): "simulated" | "measured" {
138	  return kind === "fake" ? "simulated" : "measured";
139	}
140	
141	function fileSafe(label: string): string {
142	  return label.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "run";
143	}
144	
145	// Delegates to the real or fake client and records only the hashes of the
146	// system messages it is asked to send, never their text.
147	class HashingLlmClient implements LlmClient {
148	  readonly system_hashes = new Set<string>();
149	
150	  constructor(private readonly inner: LlmClient) {}
151	
152	  get records_llm_spans(): boolean {
153	    return this.inner.records_llm_spans;
154	  }
155	
156	  complete(request: LlmRequest): Promise<LlmResponse> {
157	    recordSystemHashes(request.messages, this.system_hashes);
158	    return this.inner.complete(request);
159	  }
160	}
161	
162	function postHocValidation(searched: readonly RawCompany[], result: PipelineResult): PostHocValidation {
163	  // The pipeline returns one prospect per searched company, in search order.
164	  return summarizeValidation(
165	    validateCompanies(searched),
166	    result.prospects.map((p) => ({
167	      company_id: p.raw.crustdata_company_id,
168	      enriched: p.enrichment.status === "enriched",
169	      delivered: p.assessment.status === "assessed",
170	    })),
171	  );
172	}
173	
174	function buildReport(
175	  args: Args,
176	  config: RunConfig,
177	  result: PipelineResult,
178	  started_at: string,
179	  prompt: { readonly system_prompt_hashes: readonly string[] },
180	  validation: PostHocValidation,
181	) {
182	  const { run, usage } = result;
183	  return {
184	    started_at,
185	    label: args.label,
186	    pipeline: args.pipeline,
187	    icp_description: EVIDENCE_ICP_DESCRIPTION,
188	    config_name: args.config,
189	    config,
190	    trace_id: run.trace_id,
191	    status: result.status,
192	    counts: run.counts,
193	    cost_usd_by_step: run.cost_usd_by_step,
194	    timings_ms_by_step: run.timings_ms_by_step,
195	    cost_basis: {
196	      provider: "simulated",
197	      provider_cost_per_record_usd: SIMULATED_COST_PER_RECORD,
198	      llm_calls_by_basis: usage.llm_cost.calls_by_basis,
199	    },
200	    provider_usage: usage.provider,
201	    llm: {
202	      mode: args.llm,
203	      token_basis: tokenBasis(args.llm),
204	      calls: usage.llm_calls,
205	      http_attempts: usage.llm_http_attempts,
206	      input_tokens: run.counts.llm_input_tokens,
207	      output_tokens: run.counts.llm_output_tokens,
208	      gateway_reported_usd: usage.llm_cost.gateway_reported_usd,
209	      estimated_usd: usage.llm_cost.estimated_usd,
210	      known_usd: usage.llm_cost.known_usd,
211	      cost_complete: usage.llm_cost.complete,
212	    },
213	    prompt_provenance: {
214	      prompt_version: PROMPT_VERSION,
215	      prompt_safety_rules_sha256: sha256Hex(PROMPT_SAFETY_RULES),
216	      system_prompt_hashes: prompt.system_prompt_hashes,
217	    },
218	    post_hoc_validation: validation,
219	    issue_codes: result.issues.map((i) => i.code),
220	    company_ids: result.prospects.map((p) => p.raw.crustdata_company_id),
221	    prospects: result.prospects.map((p) => ({
222	      company_id: p.raw.crustdata_company_id,
223	      enrichment: p.enrichment.status,
224	      assessment: p.assessment.status,
225	      llm_call_number: p.llm_call?.call_number ?? null,
226	    })),
227	  };
228	}
229	
230	async function main(): Promise<void> {
231	  const args = parseArgs(process.argv.slice(2));
232	  const config = args.config === "dev" ? DEV_RUN_CONFIG : EVAL_RUN_CONFIG;
233	
234	  const provider = new FixtureProvider({ config, cost_per_record: SIMULATED_COST_PER_RECORD });
235	  const llm = new HashingLlmClient(buildLlm(args.llm));
236	  const searched: RawCompany[] = [];
237	  const recordingProvider: CompanyProvider = {
238	    autocompleteIndustry: (query) => provider.autocompleteIndustry(query),
239	    enrichCompanies: (urls) => provider.enrichCompanies(urls),
240	    async searchCompanies(filters, limit) {
241	      const res = await provider.searchCompanies(filters, limit);
242	      if (res.ok) searched.push(...res.data);
243	      return res;
244	    },
245	  };
246	  const started_at = new Date().toISOString();
247	
248	  await initTracing({ run_label: args.label });
249	  let result: PipelineResult;
250	  try {
251	    const run = span({ kind: "WORKFLOW", name: "signalscout_run" }, () =>
252	      runBaselinePipeline(
253	        EVIDENCE_ICP,
254	        { provider: recordingProvider, budget: provider.budget, llm, tracer: neatlogsTracer },
255	        { config },
256	      ),
257	    );
258	    result = await run();
259	  } finally {
260	    await closeTracing();
261	  }
262	
263	  const system_prompt_hashes = [...llm.system_hashes].sort();
264	  const validation = postHocValidation(searched, result);
265	  const report = buildReport(args, config, result, started_at, { system_prompt_hashes }, validation);
266	  await mkdir("runs", { recursive: true });
267	  const path = `runs/${started_at.replace(/[:.]/g, "-")}-${fileSafe(args.label)}.json`;
268	  await writeFile(path, `${JSON.stringify(report, null, 2)}\n`);
269	
270	  const { counts, cost_usd_by_step: cost } = result.run;
271	  const llmCost = result.usage.llm_cost;
272	  console.log(`run ${result.run.trace_id}  status=${result.status}  label=${args.label}`);
273	  console.log(
274	    `counts   searched=${counts.searched} enriched=${counts.enriched} delivered=${counts.delivered} llm_calls=${counts.llm_calls}`,
275	  );
276	  console.log(`tokens   in=${counts.llm_input_tokens} out=${counts.llm_output_tokens}  (${tokenBasis(args.llm)})`);
277	  console.log(
278	    `provider search=$${cost.search.toFixed(3)} enrich=$${cost.enrich.toFixed(3)}  (simulated at measured Crustdata prices)`,
279	  );
280	  console.log(
281	    `llm      gateway_reported=$${llmCost.gateway_reported_usd.toFixed(4)} (${llmCost.calls_by_basis.gateway_reported} calls)` +
282	      `  estimated=$${llmCost.estimated_usd.toFixed(4)} (${llmCost.calls_by_basis.estimated} calls)` +
283	      `  unavailable=${llmCost.calls_by_basis.unavailable} calls`,
284	  );
285	  console.log(
286	    `prompt   version=${PROMPT_VERSION} safety_rules_sha256=${sha256Hex(PROMPT_SAFETY_RULES).slice(0, 12)} system_hashes=${system_prompt_hashes.join(",") || "none"}`,
287	  );
288	  const fmt = (c: { valid: number; flagged: number; rejected: number }) =>
289	    `valid=${c.valid} flagged=${c.flagged} rejected=${c.rejected}`;
290	  console.log("post-hoc validation (counts)");
291	  console.log(`  searched  ${fmt(validation.searched)}`);
292	  console.log(`  enriched  ${fmt(validation.enriched)}  wasted_enrichments=${validation.wasted_enrichments}`);
293	  console.log(`  delivered ${fmt(validation.delivered)}  duplicate_groups=${validation.delivered_duplicate_groups}`);
294	  console.log(`issues   ${result.issues.map((i) => i.code).join(", ") || "none"}`);
295	  console.log(`report   ${path}`);
296	  if (result.status === "stopped") {
297	    console.error("The run stopped early; see the issue codes above.");
298	    process.exitCode = 1;
299	  }
300	}
301	
302	main().catch((err) => {
303	  console.error(err instanceof UsageError ? err.message : `Run failed: ${err instanceof Error ? err.message : "unknown error"}`);
304	  process.exitCode = 1;
305	});
