1	// Pure helpers for scripts/run-pipeline.ts: prompt provenance hashes and
2	// post-hoc validation counts. Nothing here returns or stores company fields
3	// or message text, only counts, company ids and hashes.
4	
5	import { createHash } from "node:crypto";
6	import type { Validation, ValidationStatus } from "../src/core/types";
7	
8	export function sha256Hex(text: string): string {
9	  return createHash("sha256").update(text).digest("hex");
10	}
11	
12	// First 12 hex characters of the sha256: enough to tell prompts apart.
13	export function shortHash(text: string): string {
14	  return sha256Hex(text).slice(0, 12);
15	}
16	
17	// Adds the short hash of every system message to `into`; text is never kept.
18	export function recordSystemHashes(
19	  messages: readonly { readonly role: string; readonly content: string }[],
20	  into: Set<string>,
21	): void {
22	  for (const m of messages) {
23	    if (m.role === "system") into.add(shortHash(m.content));
24	  }
25	}
26	
27	export interface StatusCounts {
28	  readonly valid: number;
29	  readonly flagged: number;
30	  readonly rejected: number;
31	}
32	
33	export interface ProspectFlags {
34	  readonly company_id: number;
35	  readonly enriched: boolean;
36	  readonly delivered: boolean;
37	}
38	
39	export interface PostHocValidation {
40	  readonly searched: StatusCounts;
41	  readonly enriched: StatusCounts;
42	  readonly delivered: StatusCounts;
43	  readonly wasted_enrichments: number;
44	  readonly rejected_but_enriched_ids: readonly number[];
45	  readonly rejected_but_delivered_ids: readonly number[];
46	  readonly delivered_duplicate_groups: number;
47	}
48	
49	function countStatuses(statuses: readonly ValidationStatus[]): StatusCounts {
50	  return {
51	    valid: statuses.filter((s) => s === "valid").length,
52	    flagged: statuses.filter((s) => s === "flagged").length,
53	    rejected: statuses.filter((s) => s === "rejected").length,
54	  };
55	}
56	
57	// `validations[i]` is the verdict for `prospects[i]`; both are in search order.
58	export function summarizeValidation(
59	  validations: readonly Validation[],
60	  prospects: readonly ProspectFlags[],
61	): PostHocValidation {
62	  if (validations.length !== prospects.length) {
63	    throw new Error("validations and prospects must have the same length.");
64	  }
65	  const rows = prospects.map((p, i) => ({ ...p, validation: validations[i] }));
66	  const enriched = rows.filter((r) => r.enriched);
67	  const delivered = rows.filter((r) => r.delivered);
68	  const rejected = (r: (typeof rows)[number]) => r.validation.status === "rejected";
69	
70	  // A duplicate group is identified by the first-seen record it duplicates.
71	  const groups = new Set<number>();
72	  for (const r of delivered) {
73	    for (const issue of r.validation.issues) {
74	      if (issue.code === "duplicate_domain" && issue.related_company_id !== undefined) {
75	        groups.add(issue.related_company_id);
76	      }
77	    }
78	  }
79	
80	  const enrichedCounts = countStatuses(enriched.map((r) => r.validation.status));
81	  return {
82	    searched: countStatuses(validations.map((v) => v.status)),
83	    enriched: enrichedCounts,
84	    delivered: countStatuses(delivered.map((r) => r.validation.status)),
85	    wasted_enrichments: enrichedCounts.rejected,
86	    rejected_but_enriched_ids: enriched.filter(rejected).map((r) => r.company_id),
87	    rejected_but_delivered_ids: delivered.filter(rejected).map((r) => r.company_id),
88	    delivered_duplicate_groups: groups.size,
89	  };
90	}
