1	import { describe, expect, it } from "vitest";
2	import {
3	  recordSystemHashes,
4	  sha256Hex,
5	  shortHash,
6	  summarizeValidation,
7	} from "../scripts/run-metrics";
8	import type { Validation } from "../src/core/types";
9	
10	const v = (status: Validation["status"], related?: number): Validation => ({
11	  status,
12	  issues:
13	    related === undefined
14	      ? []
15	      : [{ code: "duplicate_domain", field: "primary_domain", reason: "dup", related_company_id: related }],
16	});
17	
18	describe("hashes", () => {
19	  it("uses the first 12 hex characters of sha256", () => {
20	    expect(shortHash("abc")).toBe(sha256Hex("abc").slice(0, 12));
21	    expect(shortHash("abc")).toBe("ba7816bf8f01");
22	  });
23	
24	  it("records only distinct system-message hashes", () => {
25	    const set = new Set<string>();
26	    recordSystemHashes(
27	      [
28	        { role: "system", content: "rules" },
29	        { role: "user", content: "company data" },
30	      ],
31	      set,
32	    );
33	    recordSystemHashes([{ role: "system", content: "rules" }], set);
34	    expect([...set]).toEqual([shortHash("rules")]);
35	  });
36	});
37	
38	describe("summarizeValidation", () => {
39	  it("counts statuses per stage and lists rejected ids", () => {
40	    const validations = [v("valid"), v("rejected", 1), v("flagged"), v("rejected", 1), v("rejected")];
41	    const prospects = [
42	      { company_id: 1, enriched: true, delivered: true },
43	      { company_id: 2, enriched: true, delivered: true },
44	      { company_id: 3, enriched: true, delivered: false },
45	      { company_id: 4, enriched: false, delivered: true },
46	      { company_id: 5, enriched: true, delivered: false },
47	    ];
48	    const out = summarizeValidation(validations, prospects);
49	    expect(out.searched).toEqual({ valid: 1, flagged: 1, rejected: 3 });
50	    expect(out.enriched).toEqual({ valid: 1, flagged: 1, rejected: 2 });
51	    expect(out.delivered).toEqual({ valid: 1, flagged: 0, rejected: 2 });
52	    expect(out.wasted_enrichments).toBe(2);
53	    expect(out.rejected_but_enriched_ids).toEqual([2, 5]);
54	    expect(out.rejected_but_delivered_ids).toEqual([2, 4]);
55	    expect(out.delivered_duplicate_groups).toBe(1);
56	  });
57	
58	  it("handles an empty run and rejects mismatched lengths", () => {
59	    expect(summarizeValidation([], []).searched).toEqual({ valid: 0, flagged: 0, rejected: 0 });
60	    expect(() => summarizeValidation([v("valid")], [])).toThrow();
61	  });
62	});
