1	// Improved pipeline: plan -> search -> validate_companies -> deduplicate ->
2	// enrich (eligible, unique companies; "valid" before "flagged") ->
3	// validate_companies again on the enriched records -> build_facts -> assess
4	// from facts only -> validate_assessment -> check_claims.
5	//
6	// Same options and PipelineResult as runBaselinePipeline, so a runner can
7	// switch between them; its deps additionally require fact_provider.
8	// Planning, search, enrichment mechanics, model calls, caps, retries and cost
9	// accounting are the shared ones in run-context.ts; validation and facts are
10	// the data layer's own functions. No network of its own, and no tracing
11	// setup, flush or shutdown.
12	
13	import { buildFacts } from "../data/facts";
14	import { validateCompanies } from "../data/validation";
15	import type { AnyFact, RawCompany, Validation } from "../types";
16	import { checkClaims, isCiteableFact, validateAssessment } from "./assessment-checks";
17	import { buildFactsMessages, expectedCriteria } from "./facts-prompt";
18	import type { LlmErrorCategory } from "./llm";
19	import { LLM_TEMPERATURE } from "./llm-policy";
20	import { PipelineRun, stopCategory } from "./run-context";
21	import type { TraceAttributes } from "./tracer";
22	import type {
23	  AssessmentChecks,
24	  AssessmentOutcome,
25	  BaselineProspect,
26	  CheckResult,
27	  EnrichmentOutcome,
28	  FactProvenance,
29	  IcpInput,
30	  IdCount,
31	  ImprovedPipelineDeps,
32	  ImprovedRunMetrics,
33	  LlmCallRecord,
34	  PipelineOptions,
35	  PipelineResult,
36	} from "./types";
37	
38	// Validation's own LinkedIn rule: a record without one gets missing_linkedin.
39	function hasLinkedIn(validation: Validation): boolean {
40	  return !validation.issues.some((issue) => issue.code === "missing_linkedin");
41	}
42	
43	function isDuplicate(validation: Validation): boolean {
44	  return (
45	    validation.status === "rejected" &&
46	    validation.issues.some((issue) => issue.code === "duplicate_domain")
47	  );
48	}
49	
50	// Attributes for a validate_companies span: counts and company ids per
51	// verdict, never the records themselves.
52	function validationAttributes(
53	  ids: readonly number[],
54	  validations: readonly Validation[],
55	  phase: "search" | "enriched",
56	): TraceAttributes {
57	  const idsWith = (status: Validation["status"]) =>
58	    ids.filter((_, i) => validations[i].status === status);
59	  return {
60	    "validation.phase": phase,
61	    "validation.valid_count": idsWith("valid").length,
62	    "validation.flagged_count": idsWith("flagged").length,
63	    "validation.rejected_count": idsWith("rejected").length,
64	    "validation.flagged_ids": idsWith("flagged"),
65	    "validation.rejected_ids": idsWith("rejected"),
66	    "validation.duplicate_ids": ids.filter((_, i) => isDuplicate(validations[i])),
67	    "validation.issue_codes": [
68	      ...new Set(validations.flatMap((v) => v.issues.map((i) => i.code))),
69	    ].sort(),
70	  };
71	}
72	
73	// Attributes shared by the validate_assessment and check_claims spans.
74	function findingAttributes(company_id: number, check: CheckResult): TraceAttributes {
75	  return {
76	    "company.id": company_id,
77	    "guardrail.ok": check.ok,
78	    "guardrail.error_count": check.findings.filter((f) => f.severity === "error").length,
79	    "guardrail.warning_count": check.findings.filter((f) => f.severity === "warning").length,
80	    "guardrail.finding_codes": check.findings.map((f) => f.code),
81	  };
82	}
83	
84	const idsWhere = (prospects: readonly BaselineProspect[], test: (p: BaselineProspect) => boolean): IdCount => {
85	  const company_ids = prospects.filter(test).map((p) => p.raw.crustdata_company_id);
86	  return { count: company_ids.length, company_ids };
87	};
88	
89	function tally(values: readonly string[]): Record<string, number> {
90	  const out: Record<string, number> = {};
91	  for (const v of values) out[v] = (out[v] ?? 0) + 1;
92	  return out;
93	}
94	
95	// The run's guardrail outcomes as counts and company ids (no records).
96	function improvedMetrics(
97	  prospects: readonly BaselineProspect[],
98	  eligibleIds: readonly number[],
99	  requestedIds: readonly number[],
100	): ImprovedRunMetrics {
101	  const failed = prospects.filter((p) => p.assessment.status === "failed");
102	  const violations = prospects.flatMap((p) =>
103	    (p.checks?.claims?.findings ?? [])
104	      .filter((f) => f.severity === "error")
105	      .map((f) => ({ company_id: p.raw.crustdata_company_id, code: f.code })),
106	  );
107	  const violatingIds = [...new Set(violations.map((v) => v.company_id))];
108	  return {
109	    rejected: idsWhere(prospects, (p) => p.validation?.status === "rejected" && !isDuplicate(p.validation)),
110	    flagged: idsWhere(prospects, (p) => p.validation?.status === "flagged"),
111	    duplicates_removed: idsWhere(prospects, (p) => p.validation !== undefined && isDuplicate(p.validation)),
112	    enrichment: {
113	      eligible: { count: eligibleIds.length, company_ids: eligibleIds },
114	      requested: { count: requestedIds.length, company_ids: requestedIds },
115	      enriched: idsWhere(prospects, (p) => p.enrichment.status === "enriched"),
116	    },
117	    assessments_failed: {
118	      count: failed.length,
119	      company_ids: failed.map((p) => p.raw.crustdata_company_id),
120	      by_reason: tally(failed.map((p) => (p.assessment.status === "failed" ? p.assessment.reason : ""))),
121	    },
122	    outreach_suppressed: idsWhere(prospects, (p) => p.checks?.outreach === "removed"),
123	    claim_violations: {
124	      count: violations.length,
125	      drafts: violatingIds.length,
126	      by_code: tally(violations.map((v) => v.code)),
127	      company_ids: violatingIds,
128	    },
129	  };
130	}
