132	export async function runImprovedPipeline(
133	  icp: IcpInput,
134	  deps: ImprovedPipelineDeps,
135	  options: PipelineOptions = {},
136	): Promise<PipelineResult> {
137	  // The type requires fact_provider; this also stops untyped callers, before
138	  // any provider or model call, instead of guessing the provenance.
139	  const factProvider: FactProvenance = deps.fact_provider;
140	  if (factProvider !== "fixture" && factProvider !== "crustdata") {
141	    throw new TypeError(
142	      'runImprovedPipeline needs deps.fact_provider set to "fixture" or "crustdata".',
143	    );
144	  }
145	  const run = new PipelineRun(icp, deps, options, "improved");
146	  const { config, tracer, recorder } = run;
147	  const criteria = expectedCriteria(run.criteria);
148	
149	  return run.workflow("signalscout_improved_run", async (root) => {
150	    // 1. Plan and 2. search: identical to the baseline.
151	    const filters = await run.plan();
152	    const search = await run.search(filters);
153	    if (search.kind === "stopped") return run.finish(root, "stopped", filters, []);
154	    if (search.kind === "empty") return run.finish(root, "completed_empty", filters, []);
155	    const companies = search.companies;
156	    const ids = companies.map((c) => c.crustdata_company_id);
157	
158	    // 3. Validate the search records.
159	    const searchValidations = await recorder.time("validate", () =>
160	      tracer.span(
161	        { name: "validate_companies", kind: "GUARDRAIL", input: { phase: "search", companies: ids } },
162	        async (span) => {
163	          const validations = validateCompanies(companies);
164	          span.setAttributes(validationAttributes(ids, validations, "search"));
165	          return validations;
166	        },
167	      ),
168	    );
169	
170	    // 4. Deduplicate and prioritise. Rejected records (later duplicates
171	    // included; validateCompanies() keeps the first copy) and records with no
172	    // LinkedIn URL (validation's missing_linkedin issue) cannot be enriched.
173	    // The rest go to enrichment "valid" first, then "flagged", each group in
174	    // search order, so the enrichment cap is spent on the best candidates.
175	    const { eligible, priority } = await recorder.time("validate", () =>
176	      tracer.span({ name: "deduplicate", kind: "GUARDRAIL", input: { companies: ids } }, async (span) => {
177	        const kept = companies
178	          .map((_, i) => i)
179	          .filter((i) => searchValidations[i].status !== "rejected" && hasLinkedIn(searchValidations[i]));
180	        const ordered = [
181	          ...kept.filter((i) => searchValidations[i].status === "valid"),
182	          ...kept.filter((i) => searchValidations[i].status === "flagged"),
183	        ];
184	        span.setAttributes({
185	          "dedupe.duplicate_ids": ids.filter((_, i) => isDuplicate(searchValidations[i])),
186	          "dedupe.rejected_ids": ids.filter(
187	            (_, i) => searchValidations[i].status === "rejected" && !isDuplicate(searchValidations[i]),
188	          ),
189	          "dedupe.no_linkedin_ids": ids.filter(
190	            (_, i) => searchValidations[i].status !== "rejected" && !hasLinkedIn(searchValidations[i]),
191	          ),
192	          "dedupe.eligible_count": kept.length,
193	          "enrichment.priority_ids": ordered.map((i) => ids[i]),
194	        });
195	        return { eligible: kept, priority: ordered };
196	      }),
197	    );
198	
199	    // 5. Enrich in priority order, within the cap. Outcomes and enriched
200	    // records come back by position in `priority`, so they are mapped back
201	    // through `priority` to the right companies; the result keeps search
202	    // order.
203	    const enrich = await run.enrich(priority.map((i) => companies[i]));
204	    const enrichment: EnrichmentOutcome[] = companies.map((_, i) => ({
205	      status:
206	        searchValidations[i].status === "rejected" ? "skipped_ineligible" : "skipped_no_linkedin",
207	    }));
208	    const enrichedRecords = new Map<number, RawCompany>();
209	    priority.forEach((companyIndex, k) => {
210	      enrichment[companyIndex] = enrich.outcomes[k];
211	      const record = enrich.enriched.get(k);
212	      if (record) enrichedRecords.set(companyIndex, record);
213	    });
214	    const records = companies.map((c, i) => enrichedRecords.get(i) ?? c);
215	
216	    // 6. Revalidate: enrichment can add fields (headcount, revenue) that the
217	    // size rules need, so the verdict is re-run on the final records.
218	    const validations = await recorder.time("validate", () =>
219	      tracer.span(
220	        { name: "validate_companies", kind: "GUARDRAIL", input: { phase: "enriched", companies: ids } },
221	        async (span) => {
222	          const result = validateCompanies(records);
223	          span.setAttributes({
224	            ...validationAttributes(ids, result, "enriched"),
225	            "validation.changed_ids": ids.filter(
226	              (_, i) => JSON.stringify(result[i]) !== JSON.stringify(searchValidations[i]),
227	            ),
228	          });
229	          return result;
230	        },
231	      ),
232	    );
233	
234	    // 7. Build facts from the final records and verdicts.
235	    const facts = await recorder.time("validate", () =>
236	      tracer.span({ name: "build_facts", kind: "GUARDRAIL", input: { companies: ids } }, async (span) => {
237	        const built = records.map((r, i) => buildFacts(r, validations[i], factProvider));
238	        const all = built.flat();
239	        span.setAttributes({
240	          "facts.provider": factProvider,
241	          "facts.total": all.length,
242	          "facts.citeable": all.filter(isCiteableFact).length,
243	          "facts.uncertain": all.filter((f) => f.status === "uncertain").length,
244	          "facts.cross_checked": all.filter((f) => f.status === "cross_checked").length,
245	          "facts.company_ids": ids.filter((_, i) => built[i].length > 0),
246	          "facts.empty_company_ids": ids.filter((_, i) => built[i].length === 0),
247	        });
248	        return built;
249	      }),
250	    );
251	
252	    // 8. Assess only enriched, non-rejected companies, one at a time, within
253	    // the model-call cap; then 9. validateAssessment and 10. checkClaims.
254	    const prospects = await recorder.time("assess", () =>
255	      tracer.span(
256	        { name: "assess", kind: "AGENT", input: { companies: companies.length, criteria } },
257	        async (span) => {
258	          const out: BaselineProspect[] = [];
259	          let capReached = false;
260	          let stoppedBy: LlmErrorCategory | undefined;
261	          for (let i = 0; i < companies.length; i++) {
262	            const base = {
263	              raw: records[i],
264	              enrichment: enrichment[i],
265	              search_validation: searchValidations[i],
266	              validation: validations[i],
267	              facts: facts[i],
268	            };
269	            if (validations[i].status === "rejected") {
270	              const reason = isDuplicate(validations[i]) ? "duplicate" : "rejected";
271	              out.push({ ...base, assessment: { status: "not_assessed", reason } });
272	              continue;
273	            }
274	            if (enrichment[i].status !== "enriched") {
275	              out.push({ ...base, assessment: { status: "not_assessed", reason: "not_enriched" } });
276	              continue;
277	            }
278	            if (stoppedBy) {
279	              out.push({ ...base, assessment: { status: "not_assessed", reason: "llm_stopped" } });
280	              continue;
281	            }
282	            if (!run.canCallModel()) {
283	              capReached = true;
284	              out.push({ ...base, assessment: { status: "not_assessed", reason: "llm_call_cap" } });
285	              continue;
286	            }
287	            const assessed = await assessOne(records[i], enrichment[i], validations[i], facts[i]);
288	            out.push({ ...base, ...assessed });
289	            stoppedBy = stopCategory(assessed.assessment);
290	          }
291	          run.addAssessIssues(stoppedBy, capReached);
292	          span.setAttributes({
293	            ...run.assessAttributes(out),
294	            "guardrail.invalid_assessments": out.filter(
295	              (p) => p.assessment.status === "failed" && p.assessment.reason === "invalid_assessment",
296	            ).length,
297	            "guardrail.outreach_kept": out.filter((p) => p.checks?.outreach === "kept").length,
298	            "guardrail.outreach_removed": out.filter((p) => p.checks?.outreach === "removed").length,
299	          });
300	          return out;
301	        },
302	      ),
303	    );
304	
305	    // Rejected records stay in the result but are not delivered prospects.
306	    const delivered = prospects.filter((p) => p.validation?.status !== "rejected").length;
307	    const metrics = improvedMetrics(
308	      prospects,
309	      eligible.map((i) => ids[i]),
310	      enrich.requested_indices.map((k) => ids[priority[k]]),
311	    );
312	    root.setAttributes({
313	      "improved.rejected_count": metrics.rejected.count,
314	      "improved.flagged_count": metrics.flagged.count,
315	      "improved.duplicates_removed": metrics.duplicates_removed.count,
316	      "improved.enrichment_eligible": metrics.enrichment.eligible.count,
317	      "improved.enrichment_requested": metrics.enrichment.requested.count,
318	      "improved.assessments_failed": metrics.assessments_failed.count,
319	      "improved.outreach_suppressed": metrics.outreach_suppressed.count,
320	      "improved.claim_violations": metrics.claim_violations.count,
321	    });
322	    return run.finish(root, "completed", filters, prospects, delivered, metrics);
323	
324	    async function assessOne(
325	      raw: RawCompany,
326	      enrichmentOutcome: EnrichmentOutcome,
327	      validation: Validation,
328	      companyFacts: readonly AnyFact[],
329	    ): Promise<{ assessment: AssessmentOutcome; llm_call: LlmCallRecord; checks?: AssessmentChecks }> {
330	      const messages = buildFactsMessages({
331	        icp_description: run.input_description,
332	        criteria,
333	        excluded_domains: icp.excluded_domains,
334	        company_id: raw.crustdata_company_id,
335	        facts: companyFacts,
336	      });
337	      // CHAIN, not LLM: a wrapOpenAI client records the LLM span itself.
338	      const recordsLlm = deps.llm.records_llm_spans;
339	      return tracer.span(
340	        {
341	          name: "assess_company",
342	          kind: "CHAIN",
343	          input: recordsLlm
344	            ? {
345	                company_id: raw.crustdata_company_id,
346	                enrichment_status: enrichmentOutcome.status,
347	                fact_ids: companyFacts.map((f) => f.id),
348	              }
349	            : messages,
350	          attributes: {
351	            "company.id": raw.crustdata_company_id,
352	            "company.enrichment_status": enrichmentOutcome.status,
353	            "company.validation_status": validation.status,
354	            "company.fact_count": companyFacts.length,
355	            "company.citeable_fact_count": companyFacts.filter(isCiteableFact).length,
356	            "llm.model": config.model,
357	            "llm.temperature": LLM_TEMPERATURE,
358	            "llm.max_output_tokens": config.max_output_tokens_per_call,
359	          },
360	        },
361	        async (span) => {
362	          const { response, llm_call } = await run.callModel(messages, span);
363	          const parsed = run.parseResponse(response, span);
364	          if (!parsed.ok) return { assessment: parsed.outcome, llm_call };
365	
366	          const assessmentCheck = await tracer.span(
367	            { name: "validate_assessment", kind: "GUARDRAIL", input: { company_id: raw.crustdata_company_id } },
368	            async (guard) => {
369	              const check = validateAssessment(parsed.assessment, companyFacts, criteria);
370	              guard.setAttributes({
371	                ...findingAttributes(raw.crustdata_company_id, check),
372	                "assessment.criteria_expected": criteria.length,
373	                "assessment.criteria_scored": parsed.assessment.criterion_scores.length,
374	                "assessment.referenced_fact_ids": [
375	                  ...new Set(parsed.assessment.criterion_scores.flatMap((s) => s.fact_ids)),
376	                ],
377	              });
378	              return check;
379	            },
380	          );
381	          if (!assessmentCheck.ok) {
382	            span.setAttributes({ "assess.outcome": "invalid_assessment" });
383	            const errors = assessmentCheck.findings.filter((f) => f.severity === "error");
384	            return {
385	              llm_call,
386	              assessment: {
387	                status: "failed",
388	                reason: "invalid_assessment",
389	                message: errors.map((f) => f.message).join(" "),
390	              },
391	              checks: { assessment: assessmentCheck, outreach: "none" },
392	            };
393	          }
394	
395	          const outreach = parsed.assessment.outreach;
396	          if (!outreach) {
397	            span.setAttributes({ "assess.outreach": "none" });
398	            return {
399	              llm_call,
400	              assessment: { status: "assessed", assessment: parsed.assessment },
401	              checks: { assessment: assessmentCheck, outreach: "none" },
402	            };
403	          }
404	
405	          const claims = await tracer.span(
406	            { name: "check_claims", kind: "GUARDRAIL", input: { company_id: raw.crustdata_company_id } },
407	            async (guard) => {
408	              const check = checkClaims(outreach, companyFacts);
409	              guard.setAttributes({
410	                ...findingAttributes(raw.crustdata_company_id, check),
411	                "claims.cited_fact_ids": [...new Set(outreach.cited_fact_ids)],
412	                "claims.violating_fact_ids": [
413	                  ...new Set(
414	                    check.findings.flatMap((f) => (f.severity === "error" && f.fact_id ? [f.fact_id] : [])),
415	                  ),
416	                ],
417	                "claims.outcome": check.ok ? "kept" : "removed",
418	              });
419	              return check;
420	            },
421	          );
422	          span.setAttributes({ "assess.outreach": claims.ok ? "kept" : "removed" });
423	          // Outreach that fails the claim check is dropped; the scores stand.
424	          const assessment = claims.ok
425	            ? parsed.assessment
426	            : {
427	                fit_score: parsed.assessment.fit_score,
428	                criterion_scores: parsed.assessment.criterion_scores,
429	                uncertainty_notes: parsed.assessment.uncertainty_notes,
430	              };
431	          return {
432	            llm_call,
433	            assessment: { status: "assessed", assessment },
434	            checks: { assessment: assessmentCheck, claims, outreach: claims.ok ? "kept" : "removed" },
435	          };
436	        },
437	      );
438	    }
439	  });
440	}
