1	// Naive baseline pipeline: plan -> search -> enrich -> assess. It deliberately
2	// skips validation, deduplication, buildFacts(), validateAssessment() and
3	// checkClaims(), so its trace shows what the unguarded agent does.
4	// No network of its own: data comes from the CompanyProvider and model output
5	// from the LlmClient passed in.
6	
7	import { buildAssessmentMessages } from "./assess";
8	import type { LlmErrorCategory } from "./llm";
9	import { LLM_TEMPERATURE } from "./llm-policy";
10	import { PipelineRun, stopCategory } from "./run-context";
11	import type {
12	  AssessmentOutcome,
13	  BaselineProspect,
14	  IcpInput,
15	  LlmCallRecord,
16	  PipelineDeps,
17	  PipelineOptions,
18	  PipelineResult,
19	} from "./types";
20	
21	export async function runBaselinePipeline(
22	  icp: IcpInput,
23	  deps: PipelineDeps,
24	  options: PipelineOptions = {},
25	): Promise<PipelineResult> {
26	  const run = new PipelineRun(icp, deps, options, "naive_baseline");
27	  const assessScope = options.assess ?? "all_searched";
28	  const { config, tracer, recorder } = run;
29	
30	  return run.workflow("signalscout_baseline_run", async (root) => {
31	    // 1. Plan: ICP -> SearchFilters (free industry autocomplete).
32	    const filters = await run.plan();
33	
34	    // 2. Search.
35	    const search = await run.search(filters);
36	    if (search.kind === "stopped") return run.finish(root, "stopped", filters, []);
37	    if (search.kind === "empty") return run.finish(root, "completed_empty", filters, []);
38	    const companies = search.companies;
39	
40	    // 3. Enrich in search order, within the remaining enrichment budget.
41	    const enrich = await run.enrich(companies);
42	    const pending = companies.map((company, i) => ({
43	      raw: enrich.enriched.get(i) ?? company,
44	      enrichment: enrich.outcomes[i],
45	    }));
46	
47	    // 4. Assess, one company at a time, within the model-call cap.
48	    const prospects = await recorder.time("assess", () =>
49	      tracer.span(
50	        { name: "assess", kind: "AGENT", input: { companies: pending.length, criteria: run.criteria } },
51	        async (span) => {
52	          const out: BaselineProspect[] = [];
53	          let capReached = false;
54	          let stoppedBy: LlmErrorCategory | undefined;
55	          // Sequential on purpose: no parallel model calls.
56	          for (const prospect of pending) {
57	            if (assessScope === "enriched_only" && prospect.enrichment.status !== "enriched") {
58	              out.push({ ...prospect, assessment: { status: "not_assessed", reason: "not_enriched" } });
59	              continue;
60	            }
61	            if (stoppedBy) {
62	              out.push({ ...prospect, assessment: { status: "not_assessed", reason: "llm_stopped" } });
63	              continue;
64	            }
65	            if (!run.canCallModel()) {
66	              capReached = true;
67	              out.push({ ...prospect, assessment: { status: "not_assessed", reason: "llm_call_cap" } });
68	              continue;
69	            }
70	            const { assessment, llm_call } = await assessOne(prospect);
71	            out.push({ ...prospect, assessment, llm_call });
72	            stoppedBy = stopCategory(assessment);
73	          }
74	          run.addAssessIssues(stoppedBy, capReached);
75	          span.setAttributes(run.assessAttributes(out));
76	          return out;
77	        },
78	      ),
79	    );
80	
81	    return run.finish(root, "completed", filters, prospects);
82	
83	    async function assessOne(
84	      prospect: Pick<BaselineProspect, "raw" | "enrichment">,
85	    ): Promise<{ assessment: AssessmentOutcome; llm_call: LlmCallRecord }> {
86	      const messages = buildAssessmentMessages(run.input_description, run.criteria, icp, prospect);
87	      // CHAIN, not LLM: a wrapOpenAI client records the LLM span itself, so
88	      // this span is the agent's step around it. The prompt and completion
89	      // are only captured here when the client does not record them.
90	      const recordsLlm = deps.llm.records_llm_spans;
91	      return tracer.span(
92	        {
93	          name: "assess_company",
94	          kind: "CHAIN",
95	          input: recordsLlm
96	            ? { company_id: prospect.raw.crustdata_company_id, enrichment_status: prospect.enrichment.status }
97	            : messages,
98	          attributes: {
99	            "company.id": prospect.raw.crustdata_company_id,
100	            "company.enrichment_status": prospect.enrichment.status,
101	            "llm.model": config.model,
102	            "llm.temperature": LLM_TEMPERATURE,
103	            "llm.max_output_tokens": config.max_output_tokens_per_call,
104	          },
105	        },
106	        async (span) => {
107	          const { response, llm_call } = await run.callModel(messages, span);
108	          const parsed = run.parseResponse(response, span);
109	          return {
110	            llm_call,
111	            assessment: parsed.ok ? { status: "assessed", assessment: parsed.assessment } : parsed.outcome,
112	          };
113	        },
114	      );
115	    }
116	  });
117	}
