1	// Citation metrics for a baseline run. The baseline cites fact ids without
2	// ever building facts; this re-runs the improved pipeline's own evidence
3	// layer (validateCompanies + buildFacts) over the same records the baseline
4	// result holds and checks each cited id against it. Returns counts and
5	// company ids only, never records.
6	
7	import { buildFacts } from "../data/facts";
8	import { validateCompanies } from "../data/validation";
9	import { type AnyFact, CITEABLE_FACT_STATUSES } from "../types";
10	import type {
11	  BaselineCitationMetrics,
12	  BaselineProspect,
13	  FactProvenance,
14	  PipelineResult,
15	} from "./types";
16	
17	type CitationClass = "citeable" | "missing" | "model_provider" | "uncertain" | "other_non_citeable";
18	
19	// Company id named by a fact id of the form "<company_id>:<field>".
20	function companyIdOf(factId: string): number | undefined {
21	  const prefix = /^(\d+):/.exec(factId)?.[1];
22	  return prefix === undefined ? undefined : Number(prefix);
23	}
24	
25	// Classifies every outreach citation in `prospects` against `facts`, which
26	// is index-aligned with them (facts[i] are prospect i's facts). Checks run
27	// in order: missing, model_provider, uncertain, other_non_citeable;
28	// anything else is citeable (status in CITEABLE_FACT_STATUSES, provider not
29	// "model", and the fact belongs to that company).
30	export function classifyCitations(
31	  prospects: readonly BaselineProspect[],
32	  facts: readonly (readonly AnyFact[])[],
33	  fact_provider: FactProvenance,
34	): BaselineCitationMetrics {
35	  const counts: Record<CitationClass, number> = {
36	    citeable: 0,
37	    missing: 0,
38	    model_provider: 0,
39	    uncertain: 0,
40	    other_non_citeable: 0,
41	  };
42	  let assessed = 0;
43	  let drafts = 0;
44	  let cited = 0;
45	  let crossCompany = 0;
46	  const violatingIds: number[] = [];
47	
48	  // Which company each known fact id belongs to.
49	  const owner = new Map<string, number>();
50	  prospects.forEach((p, i) => {
51	    for (const f of facts[i] ?? []) owner.set(f.id, p.raw.crustdata_company_id);
52	  });
53	
54	  prospects.forEach((p, i) => {
55	    if (p.assessment.status !== "assessed") return;
56	    assessed += 1;
57	    const outreach = p.assessment.assessment.outreach;
58	    if (!outreach) return;
59	    drafts += 1;
60	    const companyId = p.raw.crustdata_company_id;
61	    const byId = new Map((facts[i] ?? []).map((f) => [f.id, f]));
62	    let violated = false;
63	    for (const id of new Set(outreach.cited_fact_ids)) {
64	      cited += 1;
65	      const fact = byId.get(id);
66	      let kind: CitationClass;
67	      if (!fact) {
68	        kind = "missing";
69	        const named = owner.get(id) ?? companyIdOf(id);
70	        if (named !== undefined && named !== companyId) crossCompany += 1;
71	      } else if (fact.source.provider === "model") {
72	        kind = "model_provider";
73	      } else if (fact.status === "uncertain") {
74	        kind = "uncertain";
75	      } else if (!CITEABLE_FACT_STATUSES.includes(fact.status)) {
76	        kind = "other_non_citeable";
77	      } else {
78	        kind = "citeable";
79	      }
80	      counts[kind] += 1;
81	      if (kind !== "citeable") violated = true;
82	    }
83	    if (violated) violatingIds.push(companyId);
84	  });
85	
86	  return {
87	    fact_provider,
88	    prospects: prospects.length,
89	    assessed,
90	    outreach_drafts: drafts,
91	    cited_fact_ids: cited,
92	    ...counts,
93	    cross_company: crossCompany,
94	    drafts_with_violations: { count: violatingIds.length, company_ids: violatingIds },
95	  };
96	}
97	
98	// Measures a baseline result's outreach citations with validateCompanies()
99	// and buildFacts() over that result's own records (enriched where the
100	// baseline enriched, search records otherwise), in result order.
101	// fact_provider must be stated: it is never guessed.
102	export function computeBaselineCitationMetrics(
103	  result: PipelineResult,
104	  fact_provider: FactProvenance,
105	): BaselineCitationMetrics {
106	  if (fact_provider !== "fixture" && fact_provider !== "crustdata") {
107	    throw new TypeError('computeBaselineCitationMetrics needs fact_provider "fixture" or "crustdata".');
108	  }
109	  const records = result.prospects.map((p) => p.raw);
110	  const validations = validateCompanies(records);
111	  const facts = records.map((r, i) => buildFacts(r, validations[i], fact_provider));
112	  return classifyCitations(result.prospects, facts, fact_provider);
113	}
