303	    name: str(pick(o, "basic_info.name")),
304	    primary_domain: str(pick(o, "basic_info.primary_domain")),
305	    website: str(pick(o, "basic_info.website")),
306	    professional_network_url: str(pick(o, "basic_info.professional_network_url")),
307	    employee_count_range: str(pick(o, "basic_info.employee_count_range")),
308	    industry: str(pick(o, "taxonomy.professional_network_industry")),
309	    logo: str(pick(o, "basic_info.logo_permalink")),
