316	// One element per input URL; takes the highest-confidence match, if any.
317	function mapEnrichElement(element: unknown, retrieved_at: string): RawCompany | undefined {
318	  const matches = asRecord(element)?.matches;
319	  if (!Array.isArray(matches)) return undefined;
320	  let best: Record<string, unknown> | undefined;
321	  let best_score = -Infinity;
322	  for (const m of matches) {
323	    const rec = asRecord(m);
324	    if (!rec || !asRecord(rec.company_data)) continue;
325	    const score = num(rec.confidence_score) ?? 0;
326	    if (score > best_score) {
327	      best = rec;
328	      best_score = score;
329	    }
330	  }
331	  const d = asRecord(best?.company_data);
332	  if (!d) return undefined;
333	
334	  const basic = asRecord(d.basic_info);
335	  const loc = asRecord(d.locations);
336	  const tax = asRecord(d.taxonomy);
337	
338	  // Only city / state / country are ever copied from locations.
339	  const location: { -readonly [K in keyof RawLocation]: RawLocation[K] } = {};
340	  if (str(loc?.city) !== "") location.city = str(loc?.city);
341	  if (str(loc?.state) !== "") location.state = str(loc?.state);
342	  if (str(loc?.country) !== "") location.country = str(loc?.country);
343	
344	  const founded = num(basic?.year_founded);
345	  const headcount = num(asRecord(d.headcount)?.total);
346	  const description = str(basic?.description);
347	  const legal_type = str(basic?.company_type);
348	  const specialities = Array.isArray(tax?.professional_network_specialities)
349	    ? (tax.professional_network_specialities as unknown[]).filter(
350	        (s): s is string => typeof s === "string" && s !== "",
351	      )
352	    : [];
353	
354	  return {
355	    crustdata_company_id: num(d.crustdata_company_id) ?? 0,
356	    name: str(basic?.name),
357	    primary_domain: str(basic?.primary_domain),
358	    website: str(basic?.website),
359	    professional_network_url: str(basic?.professional_network_url),
360	    employee_count_range: str(basic?.employee_count_range),
361	    industry: str(tax?.professional_network_industry),
362	    logo: str(basic?.logo_permalink),
363	    ...(description !== "" && { description }),
364	    ...(legal_type !== "" && { legal_type }),
365	    ...(founded !== undefined && { founded_year: founded }),
366	    ...(headcount !== undefined && { latest_headcount: headcount }),
367	    ...(Object.keys(location).length > 0 && { location }),
368	    ...(specialities.length > 0 && { specialities }),
369	    source: "enrich",
370	    retrieved_at,
371	    cost_usd: CRUSTDATA_PRICE_PER_ENRICHED_COMPANY_USD,
372	  };
373	}
